/// Animatable reference holding a default value and animation link
///
/// Holds both a constant default value and a link to keyframed animation data. If
/// animId == 0, the property is not animated — use initValue as a constant. Otherwise,
/// resolve through STC_.animIds to locate keyframe data. Total size depends on
/// sizeof(T): 12 + 2*sizeof(T) + 4 bytes.
///
/// @tparam T The value type (f32, Vector3f, Quaternion, ColorBGRA, Extent, etc.)
template <class T>
struct M3AnimRef {
    /// Interpolation: 0=none/step, 1=linear, 2=hermite, 3=bezier
    u16 interpType{};
    /// Animation flags
    u16 flags{};
    /// Animation identifier (links to STC animation data; 0=not animated)
    u32 animId{};
    /// Initial/default value (used when not animated)
    T initValue{};
    /// Null/reset value
    T nullValue{};
    /// Typically -1
    i32 unused{};

    template <class V>
    void reflect(V& v) {
        v.field("interpType", interpType);
        v.field("flags", flags);
        v.field("animId", animId);
        v.field("initValue", initValue);
        v.field("nullValue", nullValue);
        v.field("unused", unused);
    }
};

/// Color stored as BGRA (4 bytes)
///
/// Blue-green-red-alpha byte order, matching the M3 on-disk format.
struct M3ColorBGRA {
    /// Blue channel
    u8 b{};
    /// Green channel
    u8 g{};
    /// Red channel
    u8 r{};
    /// Alpha channel
    u8 a{};

    template <class V>
    void reflect(V& v) {
        v.field("b", b);
        v.field("g", g);
        v.field("r", r);
        v.field("a", a);
    }
};

/// LAYR — Texture layer (v0–v26, 352–464 bytes)
///
/// A single texture binding with animated color tint, UV transforms, flipbook
