        v.field("color", color);
        v.field("flags", flags);
        v.field("uvMapping", uvMapping);
        v.field("colorType", colorType);
        v.field("rgbMultiply", rgbMultiply);
        v.field("rgbAdd", rgbAdd);
        v.field("pocTexture", pocTexture);
