        v.field("aviStop", aviStop);
        v.field("aviLoop", aviLoop);
        v.field("aviSync", aviSync);
        v.field("aviPlay", aviPlay);
        v.field("aviRestart", aviRestart);
        v.field("flipbookRows", flipbookRows);
