/// MAT_ — Standard material (v0–v20, 268–352 bytes)
///
/// The primary material type with up to 18 texture layers (diffuse, specular, emissive,
/// normal, height, etc.), blend mode, HDR multipliers, and per-version extensions for
/// normal-blend and gloss layers.
struct M3Standard {
    /// Material name (Ref<CHAR>)
    std::string name;
    /// Additional flags
    M3MaterialAdditionalFlag additionalFlags{};
    /// Material rendering flags
    M3MaterialFlag flags{};
    /// Alpha blend mode
    M3BlendMode blendMode{};
    /// Render priority (lower = earlier)
    i32 priority{};
    /// RTT channel mask
    u32 rttChannels{};
    /// Specular highlight exponent
    f32 specularExponent{};
    /// Depth blend falloff distance
    f32 depthBlendFalloff{};
    /// Alpha test cut-off value
    u32 alphaTestThreshold{};
    /// HDR specular multiplier
    f32 hdrSpecularMultiplier{};
    /// HDR emissive multiplier
    f32 hdrEmissiveMultiplier{};
    /// HDR environment constant (v20)
    f32 hdrEnvironmentConstant{};
    /// HDR environment diffuse (v20)
    f32 hdrEnvironmentDiffuse{};
    /// HDR environment specular (v20)
    f32 hdrEnvironmentSpecular{};
    /// Diffuse / albedo texture
    std::optional<M3TextureLayer> diffuseLayer;
    /// Decal overlay texture
    std::optional<M3TextureLayer> decalLayer;
    /// Specular map texture
    std::optional<M3TextureLayer> specularLayer;
    /// Gloss map texture (v16+)
    std::optional<M3TextureLayer> glossLayer;
    /// Emissive layer 1
    std::optional<M3TextureLayer> emissiveLayer1;
    /// Emissive layer 2
    std::optional<M3TextureLayer> emissiveLayer2;
    /// Environment reflection map
    std::optional<M3TextureLayer> environmentLayer;
    /// Environment mask
    std::optional<M3TextureLayer> environmentMaskLayer;
    /// Alpha mask layer 1
    std::optional<M3TextureLayer> alphaLayer1;
    /// Alpha mask layer 2
    std::optional<M3TextureLayer> alphaLayer2;
    /// Normal / bump map
    std::optional<M3TextureLayer> normalLayer;
    /// Height / parallax map
    std::optional<M3TextureLayer> heightLayer;
    /// Light map
    std::optional<M3TextureLayer> lightMapLayer;
    /// Ambient occlusion map
    std::optional<M3TextureLayer> ambientOcclusionLayer;
    /// Normal blend 1 mask (v19+)
    std::optional<M3TextureLayer> normalBlend1MaskLayer;
    /// Normal blend 2 mask (v19+)
    std::optional<M3TextureLayer> normalBlend2MaskLayer;
    /// Normal blend 1 map (v19+)
    std::optional<M3TextureLayer> normalBlend1Layer;
    /// Normal blend 2 map (v19+)
    std::optional<M3TextureLayer> normalBlend2Layer;
    /// Material class (unit, building, etc.)
    M3MaterialClass materialClass{};
    /// Layer blend operation
    M3LayerBlendOp layerBlendMode{};
    /// Emissive layer 1 blend mode
    M3LayerBlendOp emissiveBlendMode1{};
    /// Emissive layer 2 blend mode
    M3LayerBlendOp emissiveBlendMode2{};
    /// Specular computation mode
    M3SpecularMode specularMode{};
    /// Animated parallax height
    M3AnimRef<f32> parallaxHeight{};
    /// Animated motion blur amount
    M3AnimRef<f32> motionBlurAmount{};
    /// Normal blend factors (v19+)
    std::vector<M3AnimRef<f32>> normalBlendFactors;

    template <class V>
    void reflect(V& v) {
        v.field("name", name);
        v.field("additionalFlags", additionalFlags);
        v.field("flags", flags);
        v.field("blendMode", blendMode);
        v.field("priority", priority);
        v.field("rttChannels", rttChannels);
        v.field("specularExponent", specularExponent);
        v.field("depthBlendFalloff", depthBlendFalloff);
        v.field("alphaTestThreshold", alphaTestThreshold);
        v.field("hdrSpecularMultiplier", hdrSpecularMultiplier);
        v.field("hdrEmissiveMultiplier", hdrEmissiveMultiplier);
        v.field("hdrEnvironmentConstant", hdrEnvironmentConstant);
        v.field("hdrEnvironmentDiffuse", hdrEnvironmentDiffuse);
        v.field("hdrEnvironmentSpecular", hdrEnvironmentSpecular);
        v.optional("diffuseLayer", diffuseLayer);
        v.optional("decalLayer", decalLayer);
        v.optional("specularLayer", specularLayer);
        v.optional("glossLayer", glossLayer);
        v.optional("emissiveLayer1", emissiveLayer1);
        v.optional("emissiveLayer2", emissiveLayer2);
        v.optional("environmentLayer", environmentLayer);
        v.optional("environmentMaskLayer", environmentMaskLayer);
        v.optional("alphaLayer1", alphaLayer1);
        v.optional("alphaLayer2", alphaLayer2);
        v.optional("normalLayer", normalLayer);
        v.optional("heightLayer", heightLayer);
        v.optional("lightMapLayer", lightMapLayer);
        v.optional("ambientOcclusionLayer", ambientOcclusionLayer);
        v.optional("normalBlend1MaskLayer", normalBlend1MaskLayer);
        v.optional("normalBlend2MaskLayer", normalBlend2MaskLayer);
        v.optional("normalBlend1Layer", normalBlend1Layer);
        v.optional("normalBlend2Layer", normalBlend2Layer);
        v.field("materialClass", materialClass);
        v.field("layerBlendMode", layerBlendMode);
        v.field("emissiveBlendMode1", emissiveBlendMode1);
        v.field("emissiveBlendMode2", emissiveBlendMode2);
        v.field("specularMode", specularMode);
        v.field("parallaxHeight", parallaxHeight);
        v.field("motionBlurAmount", motionBlurAmount);
        v.inlineList("normalBlendFactors", normalBlendFactors);
    }
};

